          "delivery_failure-messages_after_failure",
          "sharing-recipient_reshare_status",
          "message_privacy-foreign_message_status"
        ]
      }
    },
    {
      "id": "D_REVOKE_ADMIN",
      "topic": "authority",
      "question": "原有规则允许管理员始终查看、下载文件。如果被撤销共享的同事也是管理员，撤销后是否仍保留其管理员权限？这决定撤销规则与既有管理员权限如何衔接。",
      "why": "The new wording may conflict with the confirmed independent administrator access basis.",
      "affects": [
        "revoke_share",
        "download_file"
