"""Business expectations fixed independently before implementation."""
import json
import unittest
from pathlib import Path
from tests.scenarios import CASES,scenario

class BusinessRules(unittest.TestCase):
    def test_confirmed_rules_through_http(self):
        expected=json.loads((Path(__file__).resolve().parents[1]/"acceptance.json").read_text(encoding="utf-8"))["checks"]
