"""Bind retained runtime cases to independent native context readers."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
TARGETS={"login":"sign_in","approval":"review_file","rejection":"deliver_review_notice","sharing":"share_file",
    "denials":"download_file","delivery_failure":"deliver_review_notice","concurrent_delivery":"deliver_review_notice","message_privacy":"read_message"}

def save(name,value):
    (ROOT/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")

def main():
    payload=json.loads((ROOT/"review/runtime-observations.json").read_text(encoding="utf-8"))
    plan=json.loads((ROOT/"mapping.json").read_text(encoding="utf-8"))
    cases=[]; context=[]; seen=set()
    for run in payload["runs"]:
        if run["mode"]!="on":
            continue
        if run["case"] not in plan["cases"]:
            plan["cases"].append(run["case"])
        focus=TARGETS.get(run["case"]) or run["case"].split("__",1)[1].rsplit("_",1)[0]
        for event in run["events"]:
            key=(run["case"],event["node"],event["phase"])
            if key not in seen:
                seen.add(key)
                cases.append({"case":key[0],"node":key[1],"phase":key[2]})
            phase="completion" if event["node"]==focus and event["phase"] in {"return","commit"} else "entry"
            for component in event.get("provenance",{}):
                identity=key+(component,)
                if any(row["id"]=="/".join(identity) for row in context):
                    continue
                context.append({"id":"/".join(identity),"case":key[0],"node":key[1],"phase":key[2],
                    "source":"tests/native_audit.py: independent authenticated call arguments, native result and SQLite reads at the same boundary",
                    "actual":["native_context",phase,component],"mapped":["provenance",component]})
            if event["node"]==focus:
                identity=key+("sdk-trace",)
                if not any(row["id"]=="/".join(identity) for row in context):
                    context.append({"id":"/".join(identity),"case":key[0],"node":key[1],"phase":key[2],
                        "source":"Direct native OpenTelemetry SDK current SpanContext at the invocation boundary",
                        "actual":["native_trace_id"],"mapped":["trace","trace_id"]})
    plan["context_fields"]=context
    save("mapping.json",plan)
    save("review/runtime-bindings.json",{"source":"Actual native scenario entrypoints; no expected business values are inferred from probe output.","cases":cases})
    print(json.dumps({"cases":len(plan["cases"]),"context_fields":len(context),"runtime_bindings":len(cases)}))

if __name__=="__main__":
    main()

sources.tooling/refine_model.py:
"""Reconcile native entrypoints, parameters and canonical source projections."""
import json
from observer_runtime.code_structure import enrich
from observer_runtime.bo_observer.policy.projection import project

def refine(root,model,index):
    nodes={n["id"]:n for n in model["nodes"]}
    changes={"upload_file","review_file","share_file","revoke_share","deliver_review_notice","deliver_share_notice"}
    for node in model["nodes"]:
        if node.get("layer")=="business":
            capture=node["capture"]
            capture["out"].pop("error",None)
            if node["id"] not in changes:
                keep={"view_file":{"state","file_id"},"download_file":{"file_id"},"deliver_revoke_notice":{"state","file_id"}}.get(node["id"],set())
                for key in ("state","file_id"):
                    if key not in keep:
                        capture["out"].pop(key,None)
            else:
                capture["out"]["instance_id"]="string"
            symbol=node.get("source",{}).get("symbol")
            if symbol not in {"TeamFiles.sign_in","TeamFiles.deliver_notification"}:
                capture["in"]["actor_id"]="string"
    nodes["sign_in"]["capture"]["in"]["credential_supplied"]="boolean"
    for identity in ("deliver_review_notice","deliver_share_notice","deliver_revoke_notice"):
        nodes[identity]["capture"]["in"]["fail_after_message"]="boolean"
    for identity,symbol,layer,inputs,outputs,label in [
        ("workspace","create_app.index","business",{"authenticated":"boolean"},{"file_count":"number","message_count":"number"},"文件工作区"),
        ("api_command","create_app.command","api",{"operation":"string","path":"string"},{"status":"number"},"提交表单"),
        ("api_file_info","create_app.details","api",{"file_id":"string","path":"string"},{"status":"number"},"打开文件信息"),
        ("api_workspace","create_app.index","api",{"path":"string"},{"status":"number"},"加载工作区页面")]:
        node={"id":identity,"kind":"action" if layer=="business" else "function","layer":layer,"label":identity,"summary":label,
            "source":{"path":"app/web.py","symbol":symbol},"capture":{"in":inputs,"out":outputs}}
        model["nodes"].append(node)
        model["presentation"]["names"]["nodes"][identity]={"en":identity.replace("_"," ").title(),"zh-CN":label}
    for identity in ("api_get","api_post"):
        nodes[identity]["capture"]={"in":{"path":"string"},"out":{"status":"number"}}
        nodes[identity]["source"]={"path":"app/web.py","symbol":"create_app.api_entry"}
    for node in model["nodes"]:
        if node["id"].startswith("source:"):
            node["parent"]="workspace"
    for start,end,label in [("api_workspace","workspace","Render workspace"),("api_file_info","view_file","Read authorized file information")]+[("api_command",node,"Dispatch form operation") for node in ("sign_in","sign_out","upload_file","review_file","share_file","revoke_share")]:
        model["edges"].append({"id":start+":"+end,"from":start,"to":end,"type":"flow","label":label,"evidence":"Explicit native handler dispatch."})
    cases={"upload":["approval"],"review":["approval"],"share":["sharing"],
        "view":["denials"],"download":["denials","sharing"],"revoke":["revoke_active","revoke_pending"]}
    for operation in model["policy"]["operations"]:
        operation["cases"]=cases[operation["id"]]
    model=project(model)
    nodes={n["id"]:n for n in model["nodes"]}
    plan=model["implementation"]
    plan["support"]={key:value for key,value in plan["support"].items() if index["symbols"][key]["kind"]=="function"}
    additions=[
        ("workspace","workspace",["workspace"],["app/web.py::create_app.index"]),
        ("workspace_page","workspace",["api_workspace"],["app/web.py::create_app.index"]),
        ("http_api","workspace",["api_get","api_post"],["app/web.py::create_app.api_entry"]),
        ("workspace_form","workspace",["api_command"],["app/web.py::create_app.command"]),
        ("file_information","view_file",["api_file_info"],["app/web.py::create_app.details"]),
        ("authorization","review_file",[n["id"] for n in model["nodes"] if n["id"].startswith("policy:") and any(n.get("capture",{}).values())],["app/policy.py::flag_enabled"]),
        ("storage","workspace",["db_read","db_context_read","db_write","db_transaction","db_metadata"],["app/storage.py::Connection.execute","app/storage.py::Store.transaction","app/domain.py::TeamFiles.metadata"])]
    for identity,business,owned,sources in additions:
        plan["features"].append({"id":identity,"label":identity.replace("_"," ").title(),"business_node":business,"nodes":owned,"sources":sources,"parameters":[],"cases":[]})
    for feature in plan["features"]:
        for source in feature["sources"]:
            plan["support"].pop(source,None)
            if feature["id"]=="storage":
                continue
            for parameter in index["symbols"][source]["parameters"]:
                name=parameter["name"]
                if name in {"self","cls"}:
                    continue
                node=nodes[feature["nodes"][0]]
                field,policy,reason=name,"value",""
                if name=="actor":
                    field,policy,reason="actor_id","derived","Authenticated principal ID; credentials and session tokens are excluded."
                elif name=="password":
                    field,policy,reason="credential_supplied","derived","Credential presence only."
                elif name=="content":
                    field,policy,reason="size","derived","File byte length only."
                elif feature["id"]=="http_api":
                    field,policy,reason="path","derived","Native HTTP target is /api/ plus the operation path."
                elif feature["id"]=="authorization":
                    node=nodes["policy:signed_in"]
                item={"source":source,"name":name,"node":node["id"],"direction":"in","field":field,"policy":policy}
                if reason:
                    item["reason"]=reason
                feature["parameters"].append(item)
    storage=next(feature for feature in plan["features"] if feature["id"]=="storage")
    storage["parameters"]=[
        {"source":"app/storage.py::Connection.execute","name":"sql","node":"db_read","direction":"in","field":"statement","policy":"derived","reason":"Literal-free parsed SQL shape; native credentials and values are withheld."},
        {"source":"app/storage.py::Connection.execute","name":"parameters","node":"db_read","direction":"in","field":"parameters","policy":"derived","reason":"Only the count of native SQL parameters is selected."},
        {"source":"app/domain.py::TeamFiles.metadata","name":"file","node":"db_metadata","direction":"out","field":"before","policy":"derived","reason":"Only native size and state are selected from the stored file."}]
    bindings=root/"review/runtime-bindings.json"
    if bindings.exists():
        saved=json.loads(bindings.read_text(encoding="utf-8"))
        for feature in plan["features"]:
            feature["cases"]=[item for item in saved["cases"] if item["node"] in feature["nodes"]]
    model["implementation"]=plan
    return enrich(model,index,1)

sources.tooling/verify.py:
"""Canonical project verification entrypoint; preserve the initial baseline."""
import hashlib
import json
import os
import subprocess
import shutil
import sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
sys.path.insert(0,str(ROOT/"observer_runtime"))
from observer_runtime.bo_observer.workflow.sync_config import config,snapshot

def run(name,arguments):
    completed=subprocess.run([sys.executable,"-B","-X","utf8",*arguments],cwd=ROOT,capture_output=True,text=True,encoding="utf-8")
    (LOGS/(name+".stdout.log")).write_text(completed.stdout,encoding="utf-8")
    (LOGS/(name+".stderr.log")).write_text(completed.stderr,encoding="utf-8")
    if completed.returncode:
        print(name+" failed; see "+str(LOGS/(name+".stdout.log")),flush=True)
    return completed

def main():
    global LOGS
    change=ROOT/json.loads((ROOT/".stategraph/active.json").read_text(encoding="utf-8"))["change"]
    attempt=1
    while (ROOT/"review"/f"{change.name}-attempt-{attempt:02}").exists():
        attempt+=1
    LOGS=ROOT/"review"/f"{change.name}-attempt-{attempt:02}"
    LOGS.mkdir()
    os.environ.setdefault("PYTHONUTF8","1")
    os.environ.setdefault("PYTHONDONTWRITEBYTECODE","1")
    os.environ.setdefault("TEAM_FILES_DB_URL","sqlite:///runtime/team-files.sqlite3")
    baseline=ROOT/".stategraph/initial-v1/baseline.json"
    before=hashlib.sha256(baseline.read_bytes()).hexdigest()
    if run("recall",["observer_runtime/change_sync.py","recall","--root",str(ROOT)]).returncode:
        return 1
    if run("build-model",["tooling/build_model.py"]).returncode:
        return 1
    if run("scan",["observer_runtime/bo_sync.py","scan","--root",str(ROOT)]).returncode:
        return 1
    cfg=config(ROOT,"sync.json")
    current=snapshot(ROOT,cfg)
    change=ROOT/json.loads((ROOT/".stategraph/active.json").read_text(encoding="utf-8"))["change"]
    review={"candidate_id":current["id"],"decisions":{
        "business":{"action":"unchanged","reason":"Preserve all confirmed native business rules and independent assertions."},
        "state_machine":{"action":"unchanged","reason":"Preserve the same native executor and declaration."},
        "abstraction":{"action":"updated","reason":"Connect each native frontend HTTP route to its source handler and user operation."},
        "probes":{"action":"updated","reason":"Upstream Flask spans own final responses; WSGI readers independently compare real status and SDK identity without duplicate request spans."}},
        "excluded_symbols":{},"requirement_changes":{"R_OBSERVE":"Complete frontend HTTP responses, parent calls and route coverage; retain every earlier protected field, case and mode."}}
    if change.name=="revoke-sharing":
        review["decisions"]["business"]={"action":"updated","reason":"The uploader can withdraw a designated pending or active share immediately; independent administrator access remains."}
        review["decisions"]["state_machine"]={"action":"updated","reason":"The existing native engine gains revoke transitions from pending and active sharing into a terminal revoked state."}
        review["decisions"]["abstraction"]["reason"]="Bind revoke source, native state, cancelled share jobs, deferred revocation notification and frontend HTTP responses."
        review["requirement_changes"]={
            "R_REVOKE":"Implement the explicitly confirmed revocation request and retain administrator access; add independent failure, retry and competing-worker cases.",
            "R_BACKGROUND":"Add cancelled original share jobs and deferred revocation jobs; preserve original review/share waiting and delivery behavior.",
            "R_ATOMIC":"Revocation state, old-job cancellation and new notice outbox commit together. Existing review/share notice and activation atomicity is unchanged.",
            "R_OBSERVE":"Extend source, native data constraints, state/path witnesses and real HTTP comparisons without removing earlier cases, fields or modes."}
    if change.name=="listener-exclusions":
        review["decisions"]["abstraction"]={"action":"unchanged","reason":"Preserve all business/state/policy declarations and graph identities; retain current API handlers and add native response cases."}
        review["decisions"]["probes"]["reason"]="The application Flask instrumentor excludes only its actual registered static route; the observer is a different HTTPServer listener. Compare unknown application paths and actual observer reads."
        review["requirement_changes"]={"R_OBSERVE":"Repair listener identity for exclusions. Extend protected native 404 comparisons and real observer read tests; preserve every earlier capture and check."}
    (change/"review.json").write_text(json.dumps(review,indent=2)+"\n",encoding="utf-8")
    result=run("inspect",["observer_runtime/change_sync.py","inspect","--root",str(ROOT)])
    if result.returncode:
        return 1
    result=run("verify",["observer_runtime/change_sync.py","verify","--root",str(ROOT)])
    if (change/"checks").exists():
        shutil.copytree(change/"checks",LOGS/"checks")
    try:
        report=json.loads(result.stdout)
        print(json.dumps({key:value.get("status") for key,value in report.get("reports",{}).items()}),flush=True)
    except (ValueError,AttributeError):
        pass
    if result.returncode:
        return 1
    for step in ("accept","check"):
        if run(step,["observer_runtime/change_sync.py",step,"--root",str(ROOT)]).returncode:
            return 1
    after=hashlib.sha256(baseline.read_bytes()).hexdigest()
    if before!=after:
        raise AssertionError("The initial baseline changed")
    (ROOT/"review/baseline-integrity.json").write_text(json.dumps({"unchanged":True,"sha256":after})+"\n",encoding="utf-8")
    print("Canonical verify, accept and check passed; original baseline is unchanged.",flush=True)
    return 0

if __name__=="__main__":
    raise SystemExit(main())

